import abc
import six
import logging


class NrarfcnCalculator(object):
    """
    Calculate NRARFCN and GSCN.
    """

    @staticmethod
    def calculate_nrarfcn(freq):
        """
        Calculate NRARFCN based on passed frequency.

        :param freq: Frequency in MHz.
        :return: NRARFCN
        """
        calc = CalculatorSelector.get_proper_calculator(freq=freq)()
        return calc.calculate_nrarfcn(freq=freq)

    @staticmethod
    def calculate_frequency_based_on_nrarfcn(nrarfcn):
        """
        Calculate frequency based on passed NRARFCN.

        :param nrarfcn: NRARFCN.
        :return: Frequency in MHz
        """
        calc = CalculatorSelector.get_proper_calculator(nrarfcn=nrarfcn)()
        return calc.calculate_frequency_based_on_nrarfcn(nrarfcn)

    @staticmethod
    def calculate_gscn(freq, **kwargs):
        """
        Calculate GSCN based on passed frequency.

        :param freq: Frequency in MHz.
        :return: GSCN
        """
        calc = CalculatorSelector.get_proper_calculator(freq=freq)()
        return calc.calculate_gscn(freq, **kwargs)

    @staticmethod
    def calculate_frequency_based_on_gscn(gscn, **kwargs):
        """
        Calculate SSref(SSB) frequency based on passed GSCN.

        :param gscn: GSCN.
        :return: Frequency in MHz
        """
        calc = CalculatorSelector.get_proper_calculator(gscn=gscn)()
        return calc.calculate_frequency_based_on_gscn(gscn, **kwargs)

    @staticmethod
    def get_aligned_gscn_and_nrarfcn(freq, scs=120, scs_ssb=240):
        """
        Calculate GSCN and NRARFCN and align it

        :param freq: Frequency in MHz.
        :param scs: SCS(Subcarrier Spacing). Could be 60/120 kHz
        :param scs_ssb: SCS(Subcarrier Spacing) SS block. Could be 120/240 kHz
        :return: GSCN
        """
        calc = CalculatorSelector.get_proper_calculator(freq=freq)()
        return calc.get_aligned_gscn_and_nrarfcn(freq, scs, scs_ssb)

    @staticmethod
    def is_nrarfcn_need_alignment(nrarfcn, scs):
        """
        Check if NRARFCN value need to be alignment. When scs is 120 then NRARFCN need to be a even number

        :param nrarfcn: Current nrarfcn value.
        :param scs: SCS(Subcarrier Spacing). Could be 60/120
        :return: True/False
        """
        calc = CalculatorSelector.get_proper_calculator(nrarfcn=nrarfcn)()
        return calc.is_nrarfcn_need_alignment(nrarfcn, scs)

    @staticmethod
    def is_gscn_need_alignment(gscn, scs_ssb):
        """
        Check if GSCN value need to be alignment. When scs_ssb is 240 then GSCN need to be a odd number

        :param gscn: Current gscn value.
        :param scs_ssb: SCS(Subcarrier Spacing) SS block. Could be 120/240
        :return: True/False
        """
        calc = CalculatorSelector.get_proper_calculator(gscn=gscn)()
        return calc.is_gscn_need_alignment(gscn, scs_ssb)


