@six.add_metaclass(abc.ABCMeta)
class GenericCalculator(object):
    def __init__(self, data, frequency_delta):
        """
        Generic class for other calculators.

        :param data: proper range from FrequencyRanges class.
        :param frequency_delta: Frequency delta in kHz.
        """

        self.data = data
        self.frequency_delta = frequency_delta

    def calculate_nrarfcn(self, freq):
        """
        Calculate NRARFCN based on passed frequency.

        :param freq: Frequency in MHz.
        :return: NRARFCN
        """
        nrarfcn = 1000 * (freq - self.data['frequency']['min']) / self.frequency_delta + self.data['nrarfcn']['min']
        return int(round(nrarfcn))

    def calculate_frequency_based_on_nrarfcn(self, nrarfcn):
        """
        Calculate frequency based on passed NRARFCN.

        :param nrarfcn: NRARFCN.
        :return: Frequency in MHz
        """
        freq = self.data['frequency']['min'] + (self.frequency_delta / 1000) * (nrarfcn - self.data['nrarfcn']['min'])
        return round(freq, 2)

    @abc.abstractmethod
    def calculate_gscn(self, freq):
        pass

    @abc.abstractmethod
    def calculate_frequency_based_on_gscn(self, gscn):
        pass

    @staticmethod
    def is_nrarfcn_need_alignment(nrarfcn, scs):
        """
        Check if NRARFCN value need to be alignment. When scs is 120 then NRARFCN need to be a even number

        :param nrarfcn: Current nrarfcn value.
        :param scs: SCS(Subcarrier Spacing). Could be 60/120
        :return: True/False
        """
        nrarfcn = int(nrarfcn)
        scs = int(scs)

        if scs == 120:
            if not nrarfcn % 2:
                return True

        return False

    @staticmethod
    def is_gscn_need_alignment(gscn, scs_ssb):
        """
        Check if GSCN value need to be alignment. When scs_ssb is 240 then GSCN need to be a odd number

        :param gscn: Current gscn value.
        :param scs_ssb: SCS(Subcarrier Spacing) SS block. Could be 120/240
        :return: True/False
        """
        gscn = int(gscn)
        scs_ssb = int(scs_ssb)

        if scs_ssb == 240:
            if gscn % 2:
                return True

        return False

    def get_aligned_gscn_and_nrarfcn(self, freq, scs=120, scs_ssb=240):
        """
        Calculate GSCN and NRARFCN and align it

        :param freq: Frequency in MHz.
        :param scs: SCS(Subcarrier Spacing). Could be 60/120 kHz
        :param scs_ssb: SCS(Subcarrier Spacing) SS block. Could be 120/240 kHz
        :return: GSCN
        """

        gscn = self.calculate_gscn(freq)
        nrarfcn = self.calculate_nrarfcn(freq)
        logging.debug("Before Alignment: GSCN: {} NRARFCN: {}".format(gscn, nrarfcn))

        if self.is_gscn_need_alignment(gscn, scs_ssb):
            freq_low = self.calculate_frequency_based_on_gscn(gscn - 1)
            freq_high = self.calculate_frequency_based_on_gscn(gscn + 1)
            diff_low = freq - freq_low
            diff_high = freq_high - freq
            gscn = gscn + 1 if diff_high < diff_low else gscn - 1

        ss_ref_freq = self.calculate_frequency_based_on_gscn(gscn)
        nrarfcn = self.calculate_nrarfcn(ss_ref_freq)

        if self.is_nrarfcn_need_alignment(nrarfcn, scs):
            freq_low = self.calculate_frequency_based_on_nrarfcn(nrarfcn - 1)
            freq_high = self.calculate_frequency_based_on_nrarfcn(nrarfcn + 1)
            diff_low = freq - freq_low
            diff_high = freq_high - freq
            nrarfcn = nrarfcn + 1 if diff_high < diff_low else nrarfcn - 1

        logging.debug("After Alignment: GSCN: {} NRARFCN: {}".format(gscn, nrarfcn))

        return gscn, nrarfcn


class LowFrequencyCalculator(GenericCalculator):
    """
    Calculator for Low Frequency: 0 - 3000 Mhz.
    """
    def __init__(self):
        super(LowFrequencyCalculator, self).__init__(data=CalculatorResources.frequency_ranges[0], frequency_delta=5)

    def calculate_gscn(self, freq, m=1):
        """
        Calculate GSCN based on passed frequency.

        :param freq: Frequency in MHz.
        :param m: could be 1, 3, 5
        :return: GSCN
        """
        n = int(round((freq * 1000 - m * 50) / 1200))
        gscn = 3 * n + (m - 3) / 2
        return int(gscn)

    def calculate_frequency_based_on_gscn(self, gscn, m=1):
        """
        Calculate SSref(SSB) frequency based on passed GSCN.

        :param gscn: GSCN
        :param m: could be 1, 3, 5
        :return: Frequency in MHz
        """

        freq = (400 * gscn - 150 * m + 600) / 1000
        return round(freq, 2)


class MidFrequencyCalculator(GenericCalculator):
    """
    Calculator for Mid Frequency: 3000 - 24250 Mhz.
    """

    def __init__(self):
        super(MidFrequencyCalculator, self).__init__(data=CalculatorResources.frequency_ranges[1], frequency_delta=15)

    def calculate_gscn(self, freq):
        """
        Calculate GSCN based on passed frequency.

        :param freq: Frequency in MHz.
        :return: GSCN
        """
        n = int(round((freq - self.data['frequency']['min']) / 1.44))
        gscn = n + self.data['gscn']['min']
        return int(gscn)

    def calculate_frequency_based_on_gscn(self, gscn):
        """
        Calculate SSref(SSB) frequency based on passed GSCN.

        :param gscn: GSCN.
        :return: Frequency in MHz
        """
        n = gscn - self.data['gscn']['min']
        freq = 3000 + n * 1.44
        return round(freq, 2)


class HighFrequencyCalculator(GenericCalculator):
    """
    Calculator for High Frequency: 24250 - 100000 Mhz.
    """
    def __init__(self):
        super(HighFrequencyCalculator, self).__init__(data=CalculatorResources.frequency_ranges[2], frequency_delta=60)

    def calculate_gscn(self, freq):
        """
        Calculate GSCN based on passed frequency.

        :param freq: Frequency in MHz.
        :return: GSCN
        """
        n = int(round((freq - self.data['frequency']['min']) / 17.28))
        gscn = n + self.data['gscn']['min']
        return int(gscn)

    def calculate_frequency_based_on_gscn(self, gscn):
        """
        Calculate SSref(SSB) frequency based on passed GSCN.

        :param gscn: GSCN.
        :return: Frequency in MHz
        """
        n = gscn - self.data['gscn']['min']
        freq = 24250.08 + n * 17.28
        return round(freq, 2)


class CalculatorSelector(object):
    """
    Select proper calculator based on one of passed parameter. freq, nrarfc, gscn
    """
    def __init__(self):
        self.calculator_mapping = [LowFrequencyCalculator, MidFrequencyCalculator, HighFrequencyCalculator]

    @classmethod
    def get_proper_calculator(cls, freq=None, nrarfcn=None, gscn=None):
        cs = cls()
        if freq:
            return cs.get_proper_calculator_based_on_frequency(freq)
        elif nrarfcn:
            return cs.get_proper_calculator_based_on_nrarfcn(nrarfcn)
        elif gscn:
            return cs.get_proper_calculator_based_on_gscn(gscn)
        else:
            raise ValueError("One of args [freq, nrarfcn, gscn] is required")

    def get_proper_calculator_based_on_frequency(self, freq):
        """
        Get proper calculator type based on passed frequency in MHz.

        :param freq: Frequency in MHz.
        :return: calculator class
        """
        for index, _range in enumerate(CalculatorResources.frequency_ranges):
            if _range['frequency']['min'] < freq < _range['frequency']['max']:
                return self.calculator_mapping[index]

    def get_proper_calculator_based_on_nrarfcn(self, nrarfcn):
        """
        Get proper calculator type based on passed NRARFCN.

        :param nrarfcn: NRARFCN.
        :return: calculator class
        """
        for index, _range in enumerate(CalculatorResources.frequency_ranges):
            if _range['nrarfcn']['min'] <= nrarfcn < _range['nrarfcn']['max']:
                return self.calculator_mapping[index]

    def get_proper_calculator_based_on_gscn(self, gscn):
        """
        Get proper calculator type based on passed GSCN.

        :param gscn: GSCN.
        :return: calculator class
        """
        for index, _range in enumerate(CalculatorResources.frequency_ranges):
            if _range['gscn']['min'] <= gscn < _range['gscn']['max']:
                return self.calculator_mapping[index]
